text:
{
  "kcs": [
    {
      "canonical_name": "极限",
      "aliases": ["数列极限", "函数极限", "limit"],
      "description": "微积分的基础，描述数列或函数在自变量变化时的趋势。"
    },
    {
      "canonical_name": "无穷小量",
      "aliases": ["infinitesimal"],
      "description": "以零为极限的变量，用于比较变化趋势的强弱。"
    },
    {
      "canonical_name": "等价无穷小",
      "aliases": ["等价无穷小替换"],
      "description": "比值为1的无穷小量，乘除运算中可替换简化极限计算。"
    },
    {
      "canonical_name": "函数的连续性",
      "aliases": ["连续", "continuity"],
      "description": "函数在某点极限值等于函数值，是微积分研究的基本性质。"
    },
    {
      "canonical_name": "导数",
      "aliases": ["导函数", "微分商", "derivative"],
      "description": "函数变化率的极限，表示曲线切线的斜率或瞬时速度。"
    },
    {
      "canonical_name": "基本初等函数导数表",
      "aliases": ["导数公式表", "derivative formulas"],
      "description": "常用基本初等函数的导数公式集合。"
    },
    {
      "canonical_name": "求导法则",
      "aliases": ["导数的四则运算", "复合函数求导", "反函数求导", "链式法则"],
      "description": "指导数运算的规则，包括和差积商、复合与反函数。"
    },
    {
      "canonical_name": "高阶导数",
      "aliases": ["high-order derivatives"],
      "description": "对函数多次求导得到的各阶导数。"
    },
    {
      "canonical_name": "隐函数求导",
      "aliases": ["隐函数微分法", "implicit differentiation"],
      "description": "对方程确定的隐函数直接求导的方法。"
    },
    {
      "canonical_name": "微分",
      "aliases": ["differential"],
      "description": "函数增量的线性主部，与导数紧密相关。"
    },
    {
      "canonical_name": "罗尔定理",
      "aliases": ["Rolle定理"],
      "description": "若函数在闭区间连续、开区间可导且端点值相等，则内有点导数为0。"
    },
    {
      "canonical_name": "拉格朗日中值定理",
      "aliases": ["拉格朗日定理", "Lagrange中值定理"],
      "description": "若函数连续且可导，则存在点使得导数等于区间平均变化率。"
    },
    {
      "canonical_name": "柯西中值定理",
      "aliases": ["Cauchy中值定理"],
      "description": "推广拉格朗日中值定理，涉及两个函数的导数比。"
    },
    {
      "canonical_name": "洛必达法则",
      "aliases": ["L'Hôpital法则"],
      "description": "利用导数求不定式极限的方法，适用于0/0或∞/∞型。"
    },
    {
      "canonical_name": "泰勒公式",
      "aliases": ["泰勒展开", "Taylor公式", "Taylor展开"],
      "description": "用多项式逼近光滑函数，含佩亚诺或拉格朗日余项。"
    },
    {
      "canonical_name": "麦克劳林展开",
      "aliases": ["Maclaurin展开"],
      "description": "泰勒公式在x=0处的特例，常用函数展开式。"
    },
    {
      "canonical_name": "不定积分",
      "aliases": ["antiderivative", "原函数"],
      "description": "导数的逆运算，得到一族原函数。"
    },
    {
      "canonical_name": "换元积分法",
      "aliases": ["变量替换法", "substitution method"],
      "description": "通过变量替换简化积分的方法。"
    },
    {
      "canonical_name": "分部积分法",
      "aliases": ["integration by parts"],
      "description": "将积分转化为更易计算形式的方法。"
    },
    {
      "canonical_name": "定积分",
      "aliases": ["definite integral", "黎曼积分"],
      "description": "函数在区间上的积分和的极限，表示面积等。"
    },
    {
      "canonical_name": "牛顿-莱布尼茨公式",
      "aliases": ["微积分基本定理", "Newton-Leibniz公式"],
      "description": "连接定积分与原函数的公式，用于计算定积分。"
    },
    {
      "canonical_name": "定积分的应用",
      "aliases": ["积分应用"],
      "description": "用定积分计算面积、体积、弧长等几何与物理量。"
    }
  ],
  "prerequisite_edges": [
    {"from": "极限", "to": "无穷小量"},
