    {"from": "导数", "to": "求导法则"},
    {"from": "导数", "to": "高阶导数"},
    {"from": "导数", "to": "隐函数求导"},
    {"from": "导数", "to": "微分"},
    {"from": "导数", "to": "罗尔定理"},
    {"from": "罗尔定理", "to": "拉格朗日中值定理"},
    {"from": "拉格朗日中值定理", "to": "柯西中值定理"},
    {"from": "柯西中值定理", "to": "洛必达法则"},
    {"from": "拉格朗日中值定理", "to": "泰勒公式"},
    {"from": "泰勒公式", "to": "麦克劳林展开"},
    {"from": "导数", "to": "不定积分"},
    {"from": "不定积分", "to": "换元积分法"},
    {"from": "不定积分", "to": "分部积分法"},
    {"from": "不定积分", "to": "定积分"},
    {"from": "定积分", "to": "牛顿-莱布尼茨公式"},
    {"from": "定积分", "to": "定积分的应用"}
  ]
}
